window.__finlexDocLoaded(10179,{"id":10179,"articles":[{"id":1000747,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Governs current US taxation of US shareholders (>=10% vote or value) owning >50% of Controlled Foreign Corporations (CFCs), covering passive/mobile Subpart F income (§951) and Global Intangible Low-Taxed Income — GILTI (§951A).","seq":0},{"id":1000748,"no":"IRC §951 / §951A / §250","heading":"CFC Ownership Test, Subpart F Income & GILTI Minimum Tax","text":"• CFC Definition (IRC §957): Foreign corporation >50% owned (vote or value) by 'US Shareholders' (each owning >=10% vote or value).\n• Subpart F (§951–§964): Immediate US inclusion of passive Foreign Personal Holding Company Income (dividends, interest, royalties) and certain base-company sales/services income.\n• GILTI (§951A): Current inclusion of CFC tested income exceeding a 10% routine return on Qualified Business Asset Investment (QBAI), partially offset by the §250 deduction and deemed-paid Foreign Tax Credits (80% haircut, separate basket, no carryforward).","seq":1},{"id":1000749,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• GILTI vs. OECD Pillar Two: GILTI aggregates CFC income globally ('global blending'), whereas OECD Pillar Two GloBE computes the 15% minimum tax jurisdiction-by-jurisdiction (making GILTI a 'blended CFC tax regime' requiring special Pillar Two allocation).","seq":2},{"id":1000750,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (Office of the Law Revision Counsel (U.S. Code)): https://uscode.house.gov/\nStatus: in_force.","seq":3}]});
